using System.Data;
using Microsoft.Data.SqlClient;

namespace LabMetricsDashboard.Services;

/// <summary>
/// Asks LRN.SnapshotGenerator to snapshot a report that is not generated by a service, so the tracker
/// never shows it as Success: today the Denial Summary page's Denial Insight tab, which the client
/// uploads and edits. One Pending row per lab + report in LRNMaster.dbo.ReportSnapshotRequest; a
/// request while one is still Pending only moves its time, so a burst of row edits is captured once,
/// after the generator's settle time.
/// </summary>
public interface IReportSnapshotRequestQueue
{
    /// <summary>Never throws: a snapshot request must not fail the user's upload or edit.</summary>
    Task RequestAsync(string labKey, string reportCode, string requestedBy, string reason, CancellationToken ct);
}

public sealed class SqlReportSnapshotRequestQueue : IReportSnapshotRequestQueue
{
    /// <summary>ReportSnapshotFile.ReportCode of the Denial Insight snapshot (LRN.ReportWorker's ReportSnapshotCodes).</summary>
    public const string DenialInsight = "DENIALINSIGHT";

    private readonly string? _connectionString;
    private readonly ILogger<SqlReportSnapshotRequestQueue> _logger;

    public SqlReportSnapshotRequestQueue(IConfiguration configuration, ILogger<SqlReportSnapshotRequestQueue> logger)
    {
        _connectionString = configuration.GetConnectionString("DefaultConnection");
        _logger = logger;
    }

    public async Task RequestAsync(string labKey, string reportCode, string requestedBy, string reason, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(_connectionString) || string.IsNullOrWhiteSpace(labKey)) return;

        // Skipped quietly until Create_ReportSnapshots.sql has created the table.
        const string sql = @"
IF OBJECT_ID(N'dbo.ReportSnapshotRequest', N'U') IS NULL RETURN;
EXEC sp_executesql N'
UPDATE dbo.ReportSnapshotRequest
SET RequestedOn = SYSUTCDATETIME(), RequestedBy = @By, Reason = @Reason
WHERE LabKey = @Lab AND ReportCode = @Code AND Status = ''Pending'';
IF @@ROWCOUNT = 0
    INSERT dbo.ReportSnapshotRequest (LabKey, ReportCode, RequestedBy, Reason)
    VALUES (@Lab, @Code, @By, @Reason);',
    N'@Lab nvarchar(100), @Code varchar(50), @By nvarchar(256), @Reason nvarchar(200)',
    @Lab = @Lab, @Code = @Code, @By = @By, @Reason = @Reason;";

        try
        {
            await using var conn = new SqlConnection(_connectionString);
            await using var cmd = new SqlCommand(sql, conn) { CommandTimeout = 15 };
            cmd.Parameters.Add("@Lab", SqlDbType.NVarChar, 100).Value = labKey;
            cmd.Parameters.Add("@Code", SqlDbType.VarChar, 50).Value = reportCode;
            cmd.Parameters.Add("@By", SqlDbType.NVarChar, 256).Value = requestedBy;
            cmd.Parameters.Add("@Reason", SqlDbType.NVarChar, 200).Value = reason.Length > 200 ? reason[..200] : reason;
            await conn.OpenAsync(ct);
            await cmd.ExecuteNonQueryAsync(ct);
        }
        catch (Exception ex) when (ex is not OperationCanceledException || !ct.IsCancellationRequested)
        {
            _logger.LogWarning(ex, "Snapshot request {Code} for lab {Lab} could not be recorded; the next change requests it again.",
                reportCode, labKey);
        }
    }
}
